"use client";

import { fetcher } from "@/lib/fetcher";
import useSWR from "swr";
import Link from "next/link";

type Bookmark = {
    id: number;
    title: string;
    url: string;
};

export default function List() {

    const { data: bookmarks, error, isLoading } = useSWR("/api/bookmarks", fetcher, {
        revalidateOnFocus: false,
        revalidateOnReconnect: false
    });

    if (isLoading) return <div>Loading...</div>;
    if (error) return <div>Error loading bookmarks: {error.message}</div>;

    return (
        <>
            <div className="space-y-4">
                {bookmarks?.map((bookmark: Bookmark) => (
                    <div className="flex flex-col md:flex-row items-center w-full max-w-4xl bg-gray-400 rounded p-4 gap-4 md:gap-20">
                        <Link
                            href={bookmark.url ?? "#"}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="px-2 text-lg md:text-2xl w-full md:w-1/4 text-blue-700 hover:underline"
                        >
                            {bookmark.title ?? "Untitled"}
                        </Link>

                        <Link
                            href={bookmark.url ?? "#"}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="px-2 text-lg md:text-2xl w-full md:flex-1 text-blue-700 hover:underline break-words"
                        >
                            {bookmark.url ?? ""}
                        </Link>

                        <button className="mt-2 md:mt-0 px-3 py-1 bg-red-500 text-white rounded w-full md:w-auto">
                            Delete
                        </button>
                    </div>))}
            </div>
        </>
    )
}